<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { equipmentApi, userApi, workOrderApi, reportApi } from '../api'
import { ElMessage } from 'element-plus'

const router=useRouter(), role=localStorage.getItem('roleCode')
const rows=ref([]),total=ref(0),loading=ref(false),createDialog=ref(false),actionDialog=ref(false),actionType=ref(''),selected=ref(null),equipment=ref([]),maintainers=ref([])
const query=reactive({page:1,size:10,keyword:'',status:'',priority:''})
const createForm=reactive({equipmentId:null,title:'',faultType:'',faultDescription:'',priority:'MEDIUM'})
const actionForm=reactive({assigneeId:null,repairDescription:'',repairCost:0,passed:true,remark:''})
const statuses={PENDING_ACCEPTANCE:'待受理',PENDING_DISPATCH:'待派单',IN_REPAIR:'维修中',PENDING_INSPECTION:'待验收',CLOSED:'已关闭',CANCELLED:'已取消'}
const statusTypes={PENDING_ACCEPTANCE:'info',PENDING_DISPATCH:'warning',IN_REPAIR:'primary',PENDING_INSPECTION:'warning',CLOSED:'success',CANCELLED:'info'}
const priorities={LOW:'低',MEDIUM:'中',HIGH:'高',URGENT:'紧急'}
const load=async()=>{loading.value=true;try{const r=await workOrderApi.page(query);rows.value=r.data.data.records;total.value=r.data.data.total}finally{loading.value=false}}
const loadOptions=async()=>{const e=await equipmentApi.page({page:1,size:100});equipment.value=e.data.data.records;if(['ADMIN','DISPATCHER'].includes(role)){const u=await userApi.maintainers();maintainers.value=u.data.data}}
const create=async()=>{await workOrderApi.create(createForm);ElMessage.success('报修工单已创建');createDialog.value=false;load()}
const openAction=(row,type)=>{selected.value=row;actionType.value=type;Object.assign(actionForm,{assigneeId:null,repairDescription:'',repairCost:0,passed:true,remark:''});actionDialog.value=true}
const submitAction=async()=>{let payload={remark:actionForm.remark};if(actionType.value==='dispatch')payload={assigneeId:actionForm.assigneeId,remark:actionForm.remark};if(actionType.value==='repair')payload={repairDescription:actionForm.repairDescription,repairCost:actionForm.repairCost,remark:actionForm.remark};if(actionType.value==='inspection')payload={passed:actionForm.passed,remark:actionForm.remark};await workOrderApi.action(selected.value.id,actionType.value,payload);ElMessage.success('操作成功');actionDialog.value=false;load()}
const actionTitle=()=>({accept:'受理工单',dispatch:'派发工单',repair:'提交维修结果',inspection:'验收工单'}[actionType.value])
const exportExcel=async()=>{const r=await reportApi.export();const url=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=url;a.download='设备运维工单.xlsx';a.click();URL.revokeObjectURL(url)}
onMounted(()=>{load();loadOptions()})
</script>

<template>
  <div class="page-head"><div><h2>运维工单</h2><p>报修、派单、维修、验收全过程留痕</p></div><div><el-button v-if="['ADMIN','DISPATCHER','ACCEPTOR'].includes(role)" @click="exportExcel">导出Excel</el-button><el-button v-if="['ADMIN','REPORTER'].includes(role)" type="primary" @click="createDialog=true"><el-icon><Plus/></el-icon>发起报修</el-button></div></div>
  <div class="panel"><div class="filters"><el-input v-model="query.keyword" clearable placeholder="工单号、标题或故障描述" @keyup.enter="load"/><el-select v-model="query.status" clearable placeholder="工单状态"><el-option v-for="(v,k) in statuses" :key="k" :label="v" :value="k"/></el-select><el-select v-model="query.priority" clearable placeholder="优先级"><el-option v-for="(v,k) in priorities" :key="k" :label="v" :value="k"/></el-select><el-button @click="query.page=1;load()">查询</el-button></div>
    <el-table v-loading="loading" :data="rows" stripe @row-dblclick="r=>router.push('/work-orders/'+r.id)"><el-table-column prop="orderNo" label="工单号" width="190"/><el-table-column prop="title" label="工单标题" min-width="180"/><el-table-column prop="faultType" label="故障类型" width="110"/><el-table-column label="优先级" width="80"><template #default="s"><span :class="s.row.priority==='URGENT'?'danger-text':''">{{priorities[s.row.priority]}}</span></template></el-table-column><el-table-column label="状态" width="105"><template #default="s"><el-tag class="status-tag" :type="statusTypes[s.row.status]">{{statuses[s.row.status]}}</el-tag></template></el-table-column><el-table-column prop="createdAt" label="创建时间" width="175"/><el-table-column label="操作" width="280" fixed="right"><template #default="s"><div class="action-row"><el-button link @click="router.push('/work-orders/'+s.row.id)">详情</el-button><el-button v-if="['ADMIN','DISPATCHER'].includes(role)&&s.row.status==='PENDING_ACCEPTANCE'" link type="primary" @click="openAction(s.row,'accept')">受理</el-button><el-button v-if="['ADMIN','DISPATCHER'].includes(role)&&s.row.status==='PENDING_DISPATCH'" link type="primary" @click="openAction(s.row,'dispatch')">派单</el-button><el-button v-if="['ADMIN','MAINTAINER'].includes(role)&&s.row.status==='IN_REPAIR'" link type="primary" @click="openAction(s.row,'repair')">维修</el-button><el-button v-if="['ADMIN','ACCEPTOR'].includes(role)&&s.row.status==='PENDING_INSPECTION'" link type="success" @click="openAction(s.row,'inspection')">验收</el-button></div></template></el-table-column></el-table><el-pagination v-model:current-page="query.page" layout="total, prev, pager, next" :total="total" @current-change="load"/></div>
  <el-dialog v-model="createDialog" title="发起设备报修" width="620px"><el-form :model="createForm" label-width="90px"><el-form-item label="故障设备"><el-select v-model="createForm.equipmentId" filterable style="width:100%"><el-option v-for="e in equipment" :key="e.id" :label="`${e.equipmentCode} · ${e.name}`" :value="e.id"/></el-select></el-form-item><el-form-item label="工单标题"><el-input v-model="createForm.title"/></el-form-item><el-form-item label="故障类型"><el-input v-model="createForm.faultType"/></el-form-item><el-form-item label="优先级"><el-radio-group v-model="createForm.priority"><el-radio-button v-for="(v,k) in priorities" :key="k" :value="k">{{v}}</el-radio-button></el-radio-group></el-form-item><el-form-item label="故障描述"><el-input v-model="createForm.faultDescription" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="createDialog=false">取消</el-button><el-button type="primary" @click="create">提交报修</el-button></template></el-dialog>
  <el-dialog v-model="actionDialog" :title="actionTitle()" width="520px"><el-form label-width="90px"><el-form-item v-if="actionType==='dispatch'" label="维修人员"><el-select v-model="actionForm.assigneeId" style="width:100%"><el-option v-for="u in maintainers" :key="u.id" :label="`${u.displayName} · ${u.department}`" :value="u.id"/></el-select></el-form-item><template v-if="actionType==='repair'"><el-form-item label="维修说明"><el-input v-model="actionForm.repairDescription" type="textarea" :rows="4"/></el-form-item><el-form-item label="维修费用"><el-input-number v-model="actionForm.repairCost" :min="0" :precision="2"/></el-form-item></template><el-form-item v-if="actionType==='inspection'" label="验收结论"><el-radio-group v-model="actionForm.passed"><el-radio-button :value="true">通过并关闭</el-radio-button><el-radio-button :value="false">驳回返修</el-radio-button></el-radio-group></el-form-item><el-form-item label="操作备注"><el-input v-model="actionForm.remark" type="textarea" :rows="3" :placeholder="actionType==='inspection'&&!actionForm.passed?'驳回时必须填写原因':'可选'"/></el-form-item></el-form><template #footer><el-button @click="actionDialog=false">取消</el-button><el-button type="primary" @click="submitAction">确认</el-button></template></el-dialog>
</template>
